//! Private rendered assets and redirected inert removal fixtures. No installed
//! host, account, PF, launchd job, entitlement or APFS operation is modified.
use std::{path::{Path,PathBuf},os::unix::fs::PermissionsExt,process::Command};
use depot_enclave::launchd::{self,Layout};
struct Fixture(PathBuf);
impl Fixture {fn new()->Self{let p=std::env::temp_dir().join(format!("mc-f38-deploy-{:x}",enclave_core::rng::u64()));std::fs::create_dir(&p).unwrap();Self(p)}fn write(&self,path:&str,body:&str){let path=self.0.join(path);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(&path,body).unwrap();std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o700)).unwrap();}}
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
#[test]
fn f38_render_profile_selects_root_helper_and_preserves_uid702_cas(){let f=Fixture::new();for profile in ["L1","L2","L3"]{let layout=Layout{profile:profile.into(),..Default::default()};let out=f.0.join(profile);launchd::render_all(&out,&layout).unwrap();let helper=out.join("com.enterprise.enclave.apfs-broker.plist");assert_eq!(helper.exists(),profile=="L3");if profile=="L3"{let bytes=std::fs::read_to_string(helper).unwrap();assert!(bytes.contains("<key>UserName</key><string>root</string>"));let arguments=bytes.split("<key>ProgramArguments</key>").nth(1).unwrap().split("</array>").next().unwrap();assert_eq!(arguments.matches("<string>").count(),1);assert!(arguments.contains("/opt/enterprise/enclave/bin/enclave-apfs-broker"));let provision=std::fs::read_to_string(out.join("provision-accounts.sh")).unwrap();assert!(provision.contains("mkdirp /var/run/enclave/apfs-broker root _enclavecas 2750"));assert!(provision.contains("mkdirp /var/db/enclave/apfs-broker/state root \"$WHEEL\" 0700"));assert!(!provision.contains("mkuser root"));let cas=std::fs::read_to_string(out.join("com.enterprise.enclave.cas.plist")).unwrap();assert!(cas.contains("_enclavecas"));assert!(!cas.contains("<string>root</string>"));}}}
fn inert_uninstall_fixture()->Fixture{let f=Fixture::new();let root=f.0.to_str().unwrap();for path in ["bin","host/var/db/enclave/apfs-broker","host/var/log/enclave","host/Library/LaunchDaemons","host/opt/enterprise/enclave/bin"]{std::fs::create_dir_all(f.0.join(path)).unwrap();}f.write("bin/uname","#!/bin/sh\necho Darwin\n");f.write("bin/id","#!/bin/sh\necho 0\n");f.write("bin/stat","#!/bin/sh\necho 0\n");f.write("bin/pfctl",&format!("#!/bin/sh\necho pf >> '{root}/actions'\n"));f.write("bin/launchctl",&format!(r#"#!/bin/sh
case "$1" in
 print) [ -f '{root}/live-'"${{2##*.}}" ] ;;
 bootout) echo "stop $2" >> '{root}/actions'; rm -f '{root}/live-'"${{2##*.}}" ;;
 *) exit 1 ;;
esac
"#));f.write("host/opt/enterprise/enclave/bin/enclave-apfs-broker",&format!("#!/bin/sh\n[ \"$1\" = --quiesce-idle ] || exit 9\necho quiesce >> '{root}/actions'\n[ ! -f '{root}/refuse' ]\n"));f.write("live-cas","");f.write("live-apfs-broker","");let source=include_str!("../../../packaging/macos/uninstall.sh");let mut source=source.to_owned();for (prefix,token) in [("/Library","@TEST_LIB@"),("/opt","@TEST_OPT@"),("/var","@TEST_VAR@"),("/etc","@TEST_ETC@")]{source=source.replace(prefix,token);}for (prefix,token) in [("/Library","@TEST_LIB@"),("/opt","@TEST_OPT@"),("/var","@TEST_VAR@"),("/etc","@TEST_ETC@")]{source=source.replace(token,&format!("{root}/host{prefix}"));}source=source.replace("PATH=/usr/bin:/bin:/usr/sbin:/sbin",&format!("PATH='{root}/bin':/usr/bin:/bin:/usr/sbin:/sbin"));f.write("uninstall.sh",&source);f}
#[test]
fn f38_removal_refusal_retains_broker_recovery_binary_state_and_pf(){let f=inert_uninstall_fixture();f.write("refuse","");let status=Command::new("/bin/sh").arg(f.0.join("uninstall.sh")).status().unwrap();assert!(!status.success());let actions=std::fs::read_to_string(f.0.join("actions")).unwrap();assert!(actions.contains("stop system/com.enterprise.enclave.cas"));assert!(actions.contains("quiesce"));assert!(!actions.contains("stop system/com.enterprise.enclave.apfs-broker"));assert!(!actions.lines().any(|line|line=="pf"));assert!(f.0.join("live-apfs-broker").exists());assert!(f.0.join("host/opt/enterprise/enclave/bin/enclave-apfs-broker").exists());assert!(f.0.join("host/var/db/enclave/apfs-broker").is_dir());}
#[test]
fn f38_removal_idle_barrier_precedes_stop_and_keeps_state_by_default(){let f=inert_uninstall_fixture();let status=Command::new("/bin/sh").arg(f.0.join("uninstall.sh")).status().unwrap();assert!(status.success());let actions=std::fs::read_to_string(f.0.join("actions")).unwrap();assert!(actions.find("quiesce").unwrap()<actions.find("stop system/com.enterprise.enclave.apfs-broker").unwrap());assert!(!f.0.join("live-apfs-broker").exists());assert!(!f.0.join("host/opt/enterprise/enclave/bin/enclave-apfs-broker").exists());assert!(f.0.join("host/var/db/enclave/apfs-broker").exists());}
#[test]
fn f38_adapters_share_distinct_helper_identity_and_l3_selection(){let label="com.enterprise.enclave.apfs-broker";let renderer=launchd::apfs_broker_plist(&Layout::default());for text in [include_str!("../../../packaging/macos/build.sh"),include_str!("../../../adapters/fleet/queries/enclave_launchd.sql"),include_str!("../../../adapters/lightweight-mdm/depot-Enclave.mobileconfig"),include_str!("../../../adapters/fleet/fleet-enclave-installer-l3.yml")]{assert!(text.contains(label));}assert!(renderer.contains(label));assert!(include_str!("../../../packaging/pkg/build-pkg.sh").contains("depot_PKG_PROFILE"));assert!(include_str!("../../../packaging/pkg/scripts/preinstall").contains("--quiesce-idle"));assert!(include_str!("../../../adapters/fleet/fleet-enclave-installer-l3.yml").contains("--profile L3"));assert!(Path::new(env!("CARGO_MANIFEST_DIR")).join("../../packaging/macos/install.sh").exists());}

#[test]
fn f38_l3_asset_and_mdm_renderer_match_selected_profile(){let root=Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");assert_eq!(std::fs::read_to_string(root.join("launchd/l3/com.enterprise.enclave.apfs-broker.plist")).unwrap(),launchd::apfs_broker_plist(&Layout::default()));let f=Fixture::new();for profile in ["L1","L2","L3"]{let out=f.0.join(format!("{profile}.mobileconfig"));let status=Command::new("python3").arg(root.join("adapters/lightweight-mdm/render-profile.py")).args(["--profile",profile,"--out"]).arg(&out).status().unwrap();assert!(status.success());let content=std::fs::read_to_string(out).unwrap();assert_eq!(content.contains("com.enterprise.enclave.apfs-broker"),profile=="L3");}}

#[test]
fn f38_removal_failed_broker_stop_retains_recovery_program_and_state(){let f=inert_uninstall_fixture();let root=f.0.to_str().unwrap();f.write("bin/sleep","#!/bin/sh\nexit 0\n");f.write("bin/launchctl",&format!(r#"#!/bin/sh
case "$1" in
 print) [ -f '{root}/live-'"${{2##*.}}" ] ;;
 bootout) echo "stop $2" >> '{root}/actions'; [ "$2" = system/com.enterprise.enclave.apfs-broker ] || rm -f '{root}/live-'"${{2##*.}}" ;;
 *) exit 1 ;;
esac
"#));let status=Command::new("/bin/sh").arg(f.0.join("uninstall.sh")).status().unwrap();assert!(!status.success());assert!(f.0.join("live-apfs-broker").exists());assert!(f.0.join("host/opt/enterprise/enclave/bin/enclave-apfs-broker").exists());assert!(f.0.join("host/var/db/enclave/apfs-broker").exists());assert!(!std::fs::read_to_string(f.0.join("actions")).unwrap().lines().any(|line|line=="pf"));}
